const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const SECONDS_PER_MINUTE = 60
const SECONDS_PER_HOUR = 60 * SECONDS_PER_MINUTE
const SECONDS_PER_DAY = 24 * SECONDS_PER_HOUR
const SECONDS_PER_MONTH = 30 * SECONDS_PER_DAY
const SECONDS_PER_YEAR = 365 * SECONDS_PER_DAY

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatTimestamp(timestamp, format, now = new Date()) {
  const date = timestamp instanceof Date ? timestamp : new Date(timestamp)

  if (Number.isNaN(date.getTime())) return ""

  switch (format) {
    case "comment":
      return formatCommentTimestamp(date, now)
    case "future":
      return formatFutureTimestamp(date, now)
    case "relative":
      return formatRelativeTimestamp(date, now)
    case "time":
      return formatTime(date)
    case "short-date":
      return formatDate(date, { month: "short", day: "numeric" })
    case "date-with-year":
      return formatDate(date, { month: "short", day: "2-digit", year: "numeric" })
    case "full-date":
      return formatDate(date, { weekday: "long", month: "long", day: "numeric" })
    case "numeric-datetime":
      return `${formatDate(date, { month: "numeric", day: "numeric", year: "2-digit" })}, ${formatTime(date)}`
    default:
      return formatDate(date, { month: "short", day: "numeric" })
  }
}

function formatCommentTimestamp(date, now) {
  const daysFromToday = signedDifferenceInDays(date, now)

  if (daysFromToday === 0) {
    return formatTime(date)
  } else if (daysFromToday === 1) {
    return "yesterday"
  } else if (daysFromToday > 1 && daysFromToday < 7) {
    return `${daysFromToday} days ago`
  } else if (daysFromToday === -1) {
    return "tomorrow"
  } else if (daysFromToday < -1 && daysFromToday > -7) {
    return `in ${Math.abs(daysFromToday)} days`
  } else {
    const options = { month: "short", day: "numeric" }
    if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
    return formatDate(date, options)
  }
}

function formatFutureTimestamp(date, now) {
  const daysUntil = signedDifferenceInDays(now, date)

  if (daysUntil === 1) {
    return "tomorrow"
  } else if (daysUntil > 1) {
    return `in ${daysUntil} days`
  } else {
    return formatRelativeTimestamp(date, now)
  }
}

function formatRelativeTimestamp(date, now) {
  const secondsUntil = (date.getTime() - now.getTime()) / 1000
  const seconds = Math.abs(secondsUntil)
  const direction = secondsUntil < 0 ? -1 : 1
  let value, unit

  if (seconds < 45) {
    return direction < 0 ? "less than a minute ago" : "in less than a minute"
  } else if (seconds < 90) {
    value = 1
    unit = "minute"
  } else if (seconds < 45 * SECONDS_PER_MINUTE) {
    value = Math.round(seconds / SECONDS_PER_MINUTE)
    unit = "minute"
  } else if (seconds < 90 * SECONDS_PER_MINUTE) {
    value = 1
    unit = "hour"
  } else if (seconds < 22 * SECONDS_PER_HOUR) {
    value = Math.round(seconds / SECONDS_PER_HOUR)
    unit = "hour"
  } else if (seconds < 36 * SECONDS_PER_HOUR) {
    value = 1
    unit = "day"
  } else if (seconds < 26 * SECONDS_PER_DAY) {
    value = Math.round(seconds / SECONDS_PER_DAY)
    unit = "day"
  } else if (seconds < 45 * SECONDS_PER_DAY) {
    value = 1
    unit = "month"
  } else if (seconds < 320 * SECONDS_PER_DAY) {
    value = Math.round(seconds / SECONDS_PER_MONTH)
    unit = "month"
  } else if (seconds < 547 * SECONDS_PER_DAY) {
    value = 1
    unit = "year"
  } else {
    value = Math.round(seconds / SECONDS_PER_YEAR)
    unit = "year"
  }

  return relativeTimeFormatter().format(direction * value, unit)
}

function formatTime(date) {
  return new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(date)
}

function formatDate(date, options) {
  return new Intl.DateTimeFormat(undefined, options).format(date)
}

let relativeTimeFormatterCache

function relativeTimeFormatter() {
  if (!relativeTimeFormatterCache) {
    relativeTimeFormatterCache = new Intl.RelativeTimeFormat(undefined, { numeric: "always" })
  }

  return relativeTimeFormatterCache
}
