    value = 1
    unit = "day"
  } else if (seconds < 26 * SECONDS_PER_DAY) {
    value = Math.round(seconds / SECONDS_PER_DAY)
    unit = "day"
  } else if (seconds < 45 * SECONDS_PER_DAY) {
    value = 1
    unit = "month"
  } else if (seconds < 320 * SECONDS_PER_DAY) {
