const SECONDS_PER_MINUTE = 60
const SECONDS_PER_HOUR = 60 * SECONDS_PER_MINUTE
const SECONDS_PER_DAY = 24 * SECONDS_PER_HOUR
const SECONDS_PER_MONTH = 30 * SECONDS_PER_DAY
const SECONDS_PER_YEAR = 365 * SECONDS_PER_DAY

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatTimestamp(timestamp, format, now = new Date(), dateOnly = false) {
  const date = dateOnly ? parseCalendarDate(timestamp) : (timestamp instanceof Date ? timestamp : new Date(timestamp))

  if (Number.isNaN(date.getTime())) return ""

  switch (format) {
    case "comment":
      return formatCommentTimestamp(date, now)
    case "future":
      return formatFutureTimestamp(date, now)
    case "relative":
      return formatRelativeTimestamp(date, now)
    case "time":
      return formatTime(date)
    case "short-date":
      return formatDate(date, { month: "short", day: "numeric" })
    case "date-with-year":
      return formatDate(date, { month: "short", day: "2-digit", year: "numeric" })
    case "full-date":
      return formatDate(date, { weekday: "long", month: "long", day: "numeric" })
    case "numeric-datetime":
      return `${formatDate(date, { month: "numeric", day: "numeric", year: "2-digit" })}, ${formatTime(date)}`
    default:
      return formatDate(date, { month: "short", day: "numeric" })
  }
}

function parseCalendarDate(value) {
  const [ year, month, day ] = value.split("-").map(Number)
  return new Date(year, month - 1, day)
}

function formatCommentTimestamp(date, now) {
  const daysFromToday = signedDifferenceInDays(date, now)

  if (daysFromToday === 0) {
    return formatTime(date)
  } else if (daysFromToday === 1) {
    return "yesterday"
  } else if (daysFromToday > 1 && daysFromToday < 7) {
    return `${daysFromToday} days ago`
  } else if (daysFromToday === -1) {
    return "tomorrow"
  } else if (daysFromToday < -1 && daysFromToday > -7) {
    return `in ${Math.abs(daysFromToday)} days`
  } else {
    const options = { month: "short", day: "numeric" }
    if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
    return formatDate(date, options)
  }
