import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatTimestamp } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" }, timestamp: String }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.#updateDescription()
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  timestampValueChanged() {
    if (this.element.isConnected && this.element.closest(this.scopeSelectorValue)) {
      this.#updateDescription()
    }
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: bridgeElement.bridgeAttribute("description")
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #updateDescription() {
    this.bridgeElement.setBridgeAttribute("description", formatTimestamp(this.timestampValue, "date-with-year"))
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatTimestamp } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"
  static values = { descriptionData: Object }

  shareUrl() {
    const description = this.hasDescriptionDataValue ? this.#formattedDescription : this.bridgeElement.bridgeAttribute("share-description")

    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }

  get #formattedDescription() {
    const { createdAt, lastActiveAt, author, assignees } = this.descriptionDataValue
    const assignedTo = assignees.length > 0
      ? `assigned to ${new Intl.ListFormat(undefined, { style: "long", type: "conjunction" }).format(assignees)}`
      : "not assigned"

    return `Added ${formatTimestamp(createdAt, "short-date")} by ${author} and ${assignedTo}. Updated ${formatTimestamp(lastActiveAt, "short-date")}`
  }
